  u jsonb; s jsonb; n jsonb; z record;
  v_old int; v_new int; v_id bigint;
  v_new_ids bigint[] := '{}';
  v_keep text[];
  v_note text := 'оновлення з таблиці Віталія, 03.10.2026';
begin
  select coalesce(array_agg(x), '{}') into v_keep from jsonb_array_elements_text(p->'keep') x;

  -- 1) наявні товари: ціна, розміри, кількість
  for u in select * from jsonb_array_elements(p->'upd') loop
    update items
       set price = u->>'price',
           extra = extra || jsonb_build_object('sizes', u->>'sizes')
     where id = (u->>'id')::bigint and site_id = 106;
    for s in select * from jsonb_array_elements(u->'stock') loop
      v_new := (s->>'qty')::int;
      select qty into v_old from stock
       where site_id = 106 and item_id = (u->>'id')::bigint and color = '' and size = s->>'size'
       limit 1;
      if found then
        if v_old <> v_new then
          update stock set qty = v_new, updated_at = now()
           where site_id = 106 and item_id = (u->>'id')::bigint and color = '' and size = s->>'size';
          insert into stock_moves (site_id, item_id, size, color, kind, delta, qty_after, note, who)
          values (106, (u->>'id')::bigint, s->>'size', '', 'fix', v_new - v_old, v_new, v_note, 'імпорт');
        end if;
      else
        insert into stock (site_id, item_id, size, color, qty)
        values (106, (u->>'id')::bigint, s->>'size', '', v_new);
        if v_new > 0 then
          insert into stock_moves (site_id, item_id, size, color, kind, delta, qty_after, note, who)
          values (106, (u->>'id')::bigint, s->>'size', '', 'in', v_new, v_new, v_note, 'імпорт');
        end if;
      end if;
    end loop;
  end loop;

  -- 2) нові картки
  for n in select * from jsonb_array_elements(p->'neu') loop
    -- повторний запуск не створить дубля
    select id into v_id from items
     where site_id = 106 and collection = 'products' and extra->>'sku' = n->>'sku' limit 1;
    if not found then
      insert into items (site_id, collection, title, text, price, image_url, extra, sort_order)
      values (106, 'products', n->>'title', n->>'text', n->>'price', '', n->'extra', 0)
      returning id into v_id;
    end if;
    v_new_ids := v_new_ids || v_id;
    for s in select * from jsonb_array_elements(n->'stock') loop
      v_new := (s->>'qty')::int;
      if not exists (select 1 from stock where site_id = 106 and item_id = v_id and color = '' and size = s->>'size') then
        insert into stock (site_id, item_id, size, color, qty) values (106, v_id, s->>'size', '', v_new);
        if v_new > 0 then
          insert into stock_moves (site_id, item_id, size, color, kind, delta, qty_after, note, who)
          values (106, v_id, s->>'size', '', 'in', v_new, v_new, v_note, 'імпорт');
        end if;
      end if;
    end loop;
  end loop;

  -- 3) усе, чого немає в таблиці, — залишок 0
  for z in
    select id, item_id, size, qty from stock
     where site_id = 106 and qty <> 0
       and not ((item_id::text || '|' || size) = any(v_keep))
       and not (item_id = any(v_new_ids))
  loop
    update stock set qty = 0, updated_at = now() where id = z.id;
    insert into stock_moves (site_id, item_id, size, color, kind, delta, qty_after, note, who)
    values (106, z.item_id, z.size, '', 'fix', -z.qty, 0, 'немає в таблиці Віталія', 'імпорт');
  end loop;
end
$imp$;

-- Що вийшло
select 'товарів у наявності' as що, count(distinct item_id)::text as скільки
  from stock where site_id = 106 and qty > 0
union all
select 'одиниць на складі', sum(qty)::text from stock where site_id = 106 and qty > 0
union all
select 'нових карток', count(*)::text from items
 where site_id = 106 and collection = 'products' and extra->>'sku' = any(array['DN1791-102','FB9109-115','3ME10121043','HQ4310-100','II1328-020','HM6803-405','HQ2181-004','FB8193-077','DR9605-010','HF0547-011','IH1159-133','FD1184-013','HM8241-010','FN7659-491__HM5764-491','FV9919-652__FV9946-652','FB7921-063__FB8002-063','FB7921-063__FB8012-063','HV0949-010__HV0959-010','FV7448-010__FV7450-010','IM6537-355__IM6540-355','HM0167-025__HM0170-025','HM7151-297__HM8241-297','HM0167-410__HM0170-410','IH8496-010__HV2346-010','IO4757-216__IO1297-216','IO4757-010__IO1297-010','IM6048-010','HJ3071-010','HJ4045-010']);
